/* Local Worker integration only. Test identity headers must never be sent to a hosted origin. */
const assert=require('node:assert/strict'),{chromium}=require('playwright');
(async()=>{const base=process.argv[2]||'http://127.0.0.1:8787',url=new URL(base);if(!['127.0.0.1','localhost'].includes(url.hostname))throw Error('This identity-fixture test only runs against a loopback Worker.');const browser=await chromium.launch(process.env.STUDENTS_BROWSER_EXECUTABLE?{executablePath:process.env.STUDENTS_BROWSER_EXECUTABLE}:{});const suffix=Date.now(),errors=[],teacher=await browser.newContext({serviceWorkers:'block',extraHTTPHeaders:{'oai-authenticated-user-id':'qa-teacher-'+suffix,'oai-authenticated-user-email':'teacher@example.test'}}),student=await browser.newContext({serviceWorkers:'block',extraHTTPHeaders:{'oai-authenticated-user-id':'qa-student-'+suffix,'oai-authenticated-user-email':'student@example.test'}}),anonymous=await browser.newContext({serviceWorkers:'block'});let classId=null;
async function view(page,hash){const target=base+'/workspace#'+hash;if(page.url()===target)await page.reload();else await page.goto(target);await page.waitForFunction(hash=>document.getElementById('workspace-view').dataset.route===hash&&document.getElementById('workspace-view').getAttribute('aria-busy')==='false',hash);assert.ok(await page.locator('#workspace-error').isHidden(),await page.locator('#workspace-error').textContent());}
try{assert.equal((await anonymous.request.get(base+'/api/workspace/session')).status(),401);const tp=await teacher.newPage(),sp=await student.newPage();for(const p of [tp,sp])p.on('pageerror',e=>errors.push(e.message));await view(tp,'projects');await tp.locator('#project-title').fill('Local integration fixture');await tp.locator('#project-create button').click();await tp.locator('#project-select').waitFor();await view(tp,'account');await tp.locator('#sync-enable').check();await tp.locator('#sync-compare').click();await tp.locator('#sync-push').click();await tp.waitForFunction(()=>document.getElementById('sync-result').textContent.includes('saved at revision'));await tp.locator('#sync-compare').click();await tp.locator('#sync-push').waitFor();const remote=await (await teacher.request.get(base+'/api/workspace/sync')).json();assert.equal(remote.revision,1);const race=await teacher.request.put(base+'/api/workspace/sync',{headers:{'if-match':String(remote.revision)},data:{backup:remote.backup}});assert.equal(race.status(),200);await tp.locator('#sync-push').click();await tp.locator('#workspace-error:not([hidden])').waitFor();assert.match(await tp.locator('#workspace-error').textContent(),/Another device changed/);assert.equal(await tp.locator('#sync-push').count(),0,'Conflicted comparison is invalidated');await view(tp,'classes');await tp.locator('#class-name').fill('QA local class');await tp.locator('#class-create button').click();await tp.locator('#assignment-preview').waitFor();classId=new URLSearchParams((await tp.url()).split('?')[1]).get('class');const info=await (await teacher.request.get(base+'/api/workspace/classes/'+classId)).json();assert.ok(info.joinCode);await tp.locator('#assignment-title').fill('Local practice assignment');await tp.locator('#assignment-count').fill('2');await tp.locator('#assignment-preview').click();await tp.locator('#assignment-save:not([disabled])').click();await tp.locator('#assignment-xml').waitFor();const assignmentId=new URLSearchParams((await tp.url()).split('?')[1]).get('assignment'),snapshot=await (await teacher.request.get(base+'/api/workspace/assignments/'+assignmentId)).json();await view(sp,'classes');await sp.locator('#class-code').fill(info.joinCode);await sp.locator('#class-display-name').fill('QA local learner');await sp.locator('#class-join button').click();await sp.locator('a[href*="assignment="]').click();await sp.locator('#assignment-submit button').waitFor();assert.equal(await sp.locator('details').count(),0,'Solutions are omitted before submission');for(const q of snapshot.items)await sp.locator('[data-assignment-answer="'+q.id+'"]').fill(String(q.expected));sp.once('dialog',d=>d.accept());await sp.locator('#assignment-submit button').click();await sp.locator('#assignment-result h2').waitFor();assert.match(await sp.locator('#assignment-result h2').textContent(),/2 \/ 2/);await view(tp,'classes?assignment='+assignmentId);assert.match(await tp.locator('table').textContent(),/QA local learner/);assert.deepEqual(errors,[]);console.log(JSON.stringify({status:'PASS',identity:'local fixtures',scope:'Actual Worker + D1 + browser: anonymous rejection, selected sync, compare-and-swap conflict, teacher class, hidden solutions, learner submission and owner roster.'}));}finally{if(classId)await teacher.request.delete(base+'/api/workspace/classes/'+classId);const snapshot=await (await teacher.request.get(base+'/api/workspace/sync')).json();await teacher.request.delete(base+'/api/workspace/sync',{headers:{'if-match':String(snapshot.revision)}});await browser.close();}})().catch(e=>{console.error(e);process.exitCode=1});
